@Service
public class CentralSubprocessRequirementControlCoverageAggregateService {
  private static final MasterDataLifecycleStatus DELETED=MasterDataLifecycleStatus.DELETED;
  private final CentralSubprocessRequirementControlCoverageRepository coverages; private final CentralSubprocessRequirementScopeRepository requirementScopes; private final CentralSubprocessControlScopeRepository controlScopes; private final CentralRegulationRequirementRepository requirements; private final CentralControlRepository controls; private final CentralSubprocessRequirementControlCoverageQueryService queries; private final MasterDataStructuralDependencyChecker dependencies; private final MasterDataAuthorizationService authorization; private final CurrentUserProvider users; private final ObjectMapper objectMapper; private final Clock clock;
  public CentralSubprocessRequirementControlCoverageAggregateService(CentralSubprocessRequirementControlCoverageRepository coverages,CentralSubprocessRequirementScopeRepository requirementScopes,CentralSubprocessControlScopeRepository controlScopes,CentralRegulationRequirementRepository requirements,CentralControlRepository controls,CentralSubprocessRequirementControlCoverageQueryService queries,MasterDataStructuralDependencyChecker dependencies,MasterDataAuthorizationService authorization,CurrentUserProvider users,ObjectMapper objectMapper,@Qualifier("masterDataRevisionClock") Clock clock){this.coverages=coverages;this.requirementScopes=requirementScopes;this.controlScopes=controlScopes;this.requirements=requirements;this.controls=controls;this.queries=queries;this.dependencies=dependencies;this.authorization=authorization;this.users=users;this.objectMapper=objectMapper;this.clock=clock;}

  public PreparedChanges prepare(RevisionExecutionContext context,CentralSubprocessEntity subprocess,MasterDataLifecycleStatus requestedSubprocessStatus,CentralSubprocessRequirementScopeAggregateService.PreparedChanges preparedRequirementScopes,CentralSubprocessControlScopeAggregateService.PreparedChanges preparedControlScopes,List<CentralRequirementControlCoverageChangeRequest> requested){requireGuard(context);List<CentralRequirementControlCoverageChangeRequest> changes=requested==null?List.of():List.copyOf(requested);if(changes.isEmpty())return new PreparedChanges(subprocess.getId(),List.of());requireAccess();validateUnique(changes);changes=changes.stream().sorted(Comparator.comparing(CentralRequirementControlCoverageChangeRequest::controlScopeId).thenComparing(CentralRequirementControlCoverageChangeRequest::requirementScopeId)).toList();List<PreparedMutation> result=new ArrayList<>();for(CentralRequirementControlCoverageChangeRequest change:changes)result.add(prepareOne(subprocess,requestedSubprocessStatus,preparedRequirementScopes,preparedControlScopes,change));return new PreparedChanges(subprocess.getId(),result);}

  private PreparedMutation prepareOne(CentralSubprocessEntity subprocess,MasterDataLifecycleStatus subprocessStatus,CentralSubprocessRequirementScopeAggregateService.PreparedChanges preparedRequirementScopes,CentralSubprocessControlScopeAggregateService.PreparedChanges preparedControlScopes,CentralRequirementControlCoverageChangeRequest change){validateShape(change);CentralSubprocessControlScopeEntity controlScope=controlScopes.lockById(change.controlScopeId()).orElseThrow(()->endpointNotFound(change.controlScopeId()));CentralControlEntity control=controls.lockById(controlScope.getControlId()).orElseThrow(()->endpointNotFound(change.controlScopeId()));CentralSubprocessRequirementScopeEntity requirementScope=requirementScopes.lockById(change.requirementScopeId()).orElseThrow(()->endpointNotFound(change.requirementScopeId()));CentralRegulationRequirementEntity risk=requirements.lockById(requirementScope.getRequirementId()).orElseThrow(()->endpointNotFound(change.requirementScopeId()));if(!subprocess.getId().equals(controlScope.getSubprocessId())||!subprocess.getId().equals(requirementScope.getSubprocessId()))throw crossSubprocess();EndpointState controlState=state(preparedControlScopes.finalState(controlScope.getId()),controlScope.getStatus(),controlScope.getValidFrom(),controlScope.getValidTo());EndpointState riskState=state(preparedRequirementScopes.finalState(requirementScope.getId()),requirementScope.getStatus(),requirementScope.getValidFrom(),requirementScope.getValidTo());CentralSubprocessRequirementControlCoverageEntity existing=coverages.lockByBusinessKey(subprocess.getId(),requirementScope.getId(),controlScope.getId()).orElse(null);if(change.operation()!=CentralRequirementControlCoverageChangeOperation.CREATE_OR_RESTORE&&(existing==null||!existing.getId().equals(change.coverageId())))throw notFound(change.coverageId());CoverageFields fields=new CoverageFields(change.validFrom(),change.validTo());validateDates(fields);
    if(change.operation()==CentralRequirementControlCoverageChangeOperation.CREATE_OR_RESTORE){requireActive(subprocess,subprocessStatus,riskState,controlState,risk,control);if(existing==null){CentralSubprocessRequirementControlCoverageEntity row=CentralSubprocessRequirementControlCoverageEntity.create(UUID.randomUUID(),subprocess.getId(),requirementScope.getId(),controlScope.getId(),fields.from(),fields.to(),actor(),Instant.now(clock));return new PreparedMutation(row,RevisionOperationType.CREATE,null,null,fields,MasterDataLifecycleStatus.ACTIVE);}if(existing.getStatus()==MasterDataLifecycleStatus.ACTIVE)throw duplicate(subprocess.getId(),requirementScope.getId(),controlScope.getId());RevisionOperationType op=existing.getStatus()==DELETED?RevisionOperationType.RESTORE:RevisionOperationType.ACTIVATE;return new PreparedMutation(existing,op,existing.getVersion(),snapshot(existing),fields,MasterDataLifecycleStatus.ACTIVE);}
    long expected=assertVersion(existing,change.version());return switch(change.operation()){
      case UPDATE->{requireNotDeleted(existing);MasterDataLifecycleStatus target=change.requestedStatus()==null?existing.getStatus():change.requestedStatus();if(target==DELETED)throw invalid("UPDATE cannot request DELETED");if(target==MasterDataLifecycleStatus.ACTIVE)requireActive(subprocess,subprocessStatus,riskState,controlState,risk,control);yield new PreparedMutation(existing,RevisionOperationType.UPDATE,expected,snapshot(existing),fields,target);}
      case ACTIVATE->{validateTransition(existing,RevisionOperationType.ACTIVATE);requireActive(subprocess,subprocessStatus,riskState,controlState,risk,control);yield current(existing,RevisionOperationType.ACTIVATE,expected);}
      case INACTIVATE->{validateTransition(existing,RevisionOperationType.INACTIVATE);yield current(existing,RevisionOperationType.INACTIVATE,expected);}
      case DELETE->{validateTransition(existing,RevisionOperationType.DELETE);if(dependencies.centralRequirementControlCoverageHasLiveDependencies(existing.getId()))throw dependency(existing.getId());yield current(existing,RevisionOperationType.DELETE,expected);}
      case RESTORE->{validateTransition(existing,RevisionOperationType.RESTORE);requireActive(subprocess,subprocessStatus,riskState,controlState,risk,control);yield current(existing,RevisionOperationType.RESTORE,expected);}
      default->throw invalid("Unsupported operation");};}

  public ApplyResult apply(PreparedChanges prepared,CentralSubprocessEntity subprocess){if(!prepared.subprocessId.equals(subprocess.getId()))throw new IllegalStateException("Prepared Coverage belongs to another Subprocess");UUID actor=actor();Instant now=Instant.now(clock);for(PreparedMutation mutation:prepared.mutations){CentralSubprocessRequirementControlCoverageEntity row=mutation.row;switch(mutation.operation){case CREATE->{}case UPDATE->{row.update(mutation.fields.from(),mutation.fields.to(),actor,now);if(mutation.requestedStatus!=row.getStatus()){if(mutation.requestedStatus==MasterDataLifecycleStatus.ACTIVE)row.activate(actor,now);else row.inactivate(actor,now);}}case ACTIVATE->row.reactivateFromCreate(mutation.fields.from(),mutation.fields.to(),actor,now);case INACTIVATE->row.inactivate(actor,now);case DELETE->row.delete(actor,now);case RESTORE->row.restoreFromCreate(mutation.fields.from(),mutation.fields.to(),actor,now);}}coverages.saveAllAndFlush(prepared.mutations.stream().map(x->x.row).toList());return new ApplyResult(prepared.mutations.stream().map(this::content).toList());}
  public List<CentralSubprocessRequirementControlCoverageResponse> canonicalRows(CentralSubprocessEntity subprocess){return authorization.canView("PROCESS")&&authorization.canView("GOVERNANCE")&&authorization.canView("CONTROL")?queries.listForSubprocess(subprocess.getId(),null,null):List.of();}
  public Set<UUID> validatedDeletionIds(RevisionExecutionContext context,CentralSubprocessEntity subprocess,List<CentralRequirementControlCoverageChangeRequest> requested){requireGuard(context);List<CentralRequirementControlCoverageChangeRequest> changes=requested==null?List.of():List.copyOf(requested);if(changes.stream().noneMatch(c->c!=null&&c.operation()==CentralRequirementControlCoverageChangeOperation.DELETE))return Set.of();requireAccess();validateUnique(changes);Set<UUID> ids=new HashSet<>();for(var change:changes.stream().filter(c->c.operation()==CentralRequirementControlCoverageChangeOperation.DELETE).sorted(Comparator.comparing(CentralRequirementControlCoverageChangeRequest::controlScopeId).thenComparing(CentralRequirementControlCoverageChangeRequest::requirementScopeId)).toList()){validateShape(change);CentralSubprocessControlScopeEntity controlScope=controlScopes.lockById(change.controlScopeId()).orElseThrow(()->endpointNotFound(change.controlScopeId()));CentralSubprocessRequirementScopeEntity requirementScope=requirementScopes.lockById(change.requirementScopeId()).orElseThrow(()->endpointNotFound(change.requirementScopeId()));if(!subprocess.getId().equals(controlScope.getSubprocessId())||!subprocess.getId().equals(requirementScope.getSubprocessId()))throw crossSubprocess();CentralSubprocessRequirementControlCoverageEntity row=coverages.lockByBusinessKey(subprocess.getId(),requirementScope.getId(),controlScope.getId()).orElseThrow(()->notFound(change.coverageId()));if(!row.getId().equals(change.coverageId()))throw notFound(change.coverageId());assertVersion(row,change.version());validateTransition(row,RevisionOperationType.DELETE);if(dependencies.centralRequirementControlCoverageHasLiveDependencies(row.getId()))throw dependency(row.getId());ids.add(row.getId());}return Set.copyOf(ids);}
  public static Set<UUID> requestedDeletionIds(List<CentralRequirementControlCoverageChangeRequest> changes){if(changes==null)return Set.of();Set<UUID> ids=new HashSet<>();for(var c:changes)if(c!=null&&c.operation()==CentralRequirementControlCoverageChangeOperation.DELETE&&c.coverageId()!=null)ids.add(c.coverageId());return Set.copyOf(ids);}

  private PreparedMutation current(CentralSubprocessRequirementControlCoverageEntity row,RevisionOperationType op,long expected){return new PreparedMutation(row,op,expected,snapshot(row),new CoverageFields(row.getValidFrom(),row.getValidTo()),row.getStatus());}
  private RevisionContentResult content(PreparedMutation m){return RevisionContentResult.completed(RevisionEntityType.CENTRAL_SUBPROCESS_REQUIREMENT_CONTROL_COVERAGE,m.row.getId(),m.operation,m.expectedVersion,m.before,snapshot(m.row),m.row.getVersion(),objectMapper.valueToTree(Map.of("validated",true,"hierarchyKey","PROCESS","lockOrder","PROCESS_GUARD_SUBPROCESS_CONTROL_RISK_REQUIREMENT_CONTROL_COVERAGE")));}
  private void validateUnique(List<CentralRequirementControlCoverageChangeRequest> changes){Set<String> pairs=new HashSet<>();Set<UUID> ids=new HashSet<>();for(var c:changes){if(c==null||c.operation()==null||c.requirementScopeId()==null||c.controlScopeId()==null)throw invalid("Each change requires operation and both typed Scope IDs");if(!pairs.add(c.requirementScopeId()+":"+c.controlScopeId()))throw invalid("Duplicate pair in one change set");if(c.coverageId()!=null&&!ids.add(c.coverageId()))throw invalid("Duplicate Coverage row in one change set");}}
  private void validateShape(CentralRequirementControlCoverageChangeRequest c){boolean create=c.operation()==CentralRequirementControlCoverageChangeOperation.CREATE_OR_RESTORE;if(create){if(c.coverageId()!=null||c.version()!=null||c.requestedStatus()!=null)throw invalid("CREATE_OR_RESTORE cannot supply coverageId, version, or requestedStatus");return;}if(c.coverageId()==null||c.version()==null||c.version()<0)throw invalid("Existing-row operations require coverageId and nonnegative version");if(c.operation()!=CentralRequirementControlCoverageChangeOperation.UPDATE&&(c.validFrom()!=null||c.validTo()!=null||c.requestedStatus()!=null))throw invalid("Explicit lifecycle operations cannot edit fields");}
  private void validateDates(CoverageFields f){if(f.from()!=null&&f.to()!=null&&f.to().isBefore(f.from()))throw new UnprocessableEntityException("DATE_RANGE_INVALID","error.masterdata.v2.invalidValidityRange","Coverage validity range is invalid");}
  private void requireActive(CentralSubprocessEntity subprocess,MasterDataLifecycleStatus subprocessStatus,EndpointState risk,EndpointState control,CentralRegulationRequirementEntity riskDefinition,CentralControlEntity controlDefinition){if(subprocessStatus!=MasterDataLifecycleStatus.ACTIVE||risk.status()!=MasterDataLifecycleStatus.ACTIVE||control.status()!=MasterDataLifecycleStatus.ACTIVE||riskDefinition.getStatus()!=MasterDataLifecycleStatus.ACTIVE||controlDefinition.getStatus()!=MasterDataLifecycleStatus.ACTIVE)throw new UnprocessableEntityException("COVERAGE_ENDPOINT_NOT_ACTIVE","error.masterdata.coverage.endpointNotActive","Coverage activation requires active Subprocess, Scopes, and definitions",subprocess.getId());}
  private EndpointState state(CentralSubprocessControlScopeAggregateService.PreparedEndpointState state,MasterDataLifecycleStatus status,LocalDate from,LocalDate to){return state==null?new EndpointState(status,from,to):new EndpointState(state.status(),state.validFrom(),state.validTo());} private EndpointState state(CentralSubprocessRequirementScopeAggregateService.PreparedEndpointState state,MasterDataLifecycleStatus status,LocalDate from,LocalDate to){return state==null?new EndpointState(status,from,to):new EndpointState(state.status(),state.validFrom(),state.validTo());}
  private long assertVersion(CentralSubprocessRequirementControlCoverageEntity row,Long version){if(version==null||version<0||row.getVersion()!=version)throw new ConflictException("VERSION_CONFLICT","error.masterdata.v2.versionConflict","Coverage has changed",row.getId());return version;}
  private void validateTransition(CentralSubprocessRequirementControlCoverageEntity row,RevisionOperationType op){boolean ok=switch(op){case ACTIVATE->row.getStatus()==MasterDataLifecycleStatus.INACTIVE;case INACTIVATE->row.getStatus()==MasterDataLifecycleStatus.ACTIVE;case DELETE->row.getStatus()!=DELETED;case RESTORE->row.getStatus()==DELETED;default->false;};if(!ok)throw new UnprocessableEntityException("INVALID_LIFECYCLE_TRANSITION","error.masterdata.v2.invalidLifecycleTransition","Invalid Coverage lifecycle transition",row.getId());}
  private void requireNotDeleted(CentralSubprocessRequirementControlCoverageEntity row){if(row.getStatus()==DELETED)throw new UnprocessableEntityException("INVALID_LIFECYCLE_TRANSITION","error.masterdata.v2.invalidLifecycleTransition","Deleted Coverage cannot be updated",row.getId());}
  private JsonNode snapshot(CentralSubprocessRequirementControlCoverageEntity r){Map<String,Object> v=new LinkedHashMap<>();v.put("id",r.getId());v.put("subprocessId",r.getSubprocessId());v.put("requirementScopeId",r.getRequirementScopeId());v.put("controlScopeId",r.getControlScopeId());v.put("status",r.getStatus().wireValue());v.put("validFrom",r.getValidFrom());v.put("validTo",r.getValidTo());v.put("version",r.getVersion());v.put("createdAt",r.getCreatedAt());v.put("createdBy",r.getCreatedBy());v.put("updatedAt",r.getUpdatedAt());v.put("updatedBy",r.getUpdatedBy());v.put("deletedAt",r.getDeletedAt());v.put("deletedBy",r.getDeletedBy());return objectMapper.valueToTree(v);}
  private void requireAccess(){authorization.requireManageWithReferences("PROCESS","GOVERNANCE","CONTROL");} private void requireGuard(RevisionExecutionContext context){if(context.acquiredHierarchyKey()!=MasterDataHierarchyKey.PROCESS)throw new IllegalStateException("Coverage changes require PROCESS guard");} private UUID actor(){return users.getCurrentPrincipal().getUserId();}
  private ConflictException duplicate(UUID subprocessId,UUID requirementScopeId,UUID controlScopeId){return new ConflictException("DUPLICATE_RELATION","error.masterdata.requirementControlCoverage.duplicate","Coverage pair already exists",subprocessId,requirementScopeId,controlScopeId);} private NotFoundException endpointNotFound(UUID id){return new NotFoundException("COVERAGE_ENDPOINT_NOT_FOUND","error.masterdata.coverage.endpointNotFound","Coverage Scope endpoint not found",id);} private NotFoundException notFound(UUID id){return new NotFoundException("REQUIREMENT_CONTROL_COVERAGE_NOT_FOUND","error.masterdata.requirementControlCoverage.notFound","Requirement-Control Coverage not found",id);} private UnprocessableEntityException crossSubprocess(){return new UnprocessableEntityException("CROSS_SUBPROCESS_COVERAGE","error.masterdata.coverage.crossSubprocess","Coverage endpoints must belong to the selected Subprocess");} private UnprocessableEntityException invalid(String message){return new UnprocessableEntityException("REQUIREMENT_CONTROL_COVERAGE_CHANGE_INVALID","error.masterdata.requirementControlCoverage.invalidChange",message);} private ConflictException dependency(UUID id){return new ConflictException("REQUIREMENT_CONTROL_COVERAGE_DEPENDENCY_CONFLICT","error.masterdata.requirementControlCoverage.dependencyConflict","Coverage has live Local dependencies",id);}
  private record EndpointState(MasterDataLifecycleStatus status,LocalDate from,LocalDate to){} private record CoverageFields(LocalDate from,LocalDate to){} private record PreparedMutation(CentralSubprocessRequirementControlCoverageEntity row,RevisionOperationType operation,Long expectedVersion,JsonNode before,CoverageFields fields,MasterDataLifecycleStatus requestedStatus){}
  public static final class PreparedChanges{private final UUID subprocessId;private final List<PreparedMutation> mutations;private PreparedChanges(UUID subprocessId,List<PreparedMutation> mutations){this.subprocessId=subprocessId;this.mutations=List.copyOf(mutations);}}
  public record ApplyResult(List<RevisionContentResult> revisionContents){public ApplyResult{revisionContents=List.copyOf(revisionContents);}}
}



